/* topomaps */
function cmap(v){ const s=[[8,12,22],[23,78,120],[63,200,255],[240,250,255]]; const x=clamp(v)*3,i=Math.min(2,Math.floor(x)),f=x-i; return s[i].map((c,j)=>Math.round(c+(s[i+1][j]-c)*f)); }
const PTS=MONT.map(n=>({n,x:P1020[n][0],y:P1020[n][1]}));
function paintTopo(cv,vals,cm=cmap){ const g=cv.getContext('2d'), S=cv.width, G=44; const img=g.createImageData(G,G), d=img.data;
  for(let j=0;j<G;j++) for(let i=0;i<G;i++){ const x=(i+.5)/G*2.2-1.1, y=1.1-(j+.5)/G*2.2, o=(j*G+i)*4; if(x*x+y*y>1.08){ d[o+3]=0; continue; }
    let num=0,den=0; for(let q=0;q<PTS.length;q++){ const dx=x-PTS[q].x, dy=y-PTS[q].y; const w=1/Math.pow(dx*dx+dy*dy+.004,1.6); num+=w*vals[q]; den+=w; } const c=cm(num/den); d[o]=c[0]; d[o+1]=c[1]; d[o+2]=c[2]; d[o+3]=255; }
  const off=paintTopo.off||(paintTopo.off=Object.assign(document.createElement('canvas'),{width:G,height:G})); off.getContext('2d').putImageData(img,0,0);
  g.clearRect(0,0,S,S); g.save(); g.beginPath(); g.arc(S/2,S/2,S/2*1.04/1.1-1,0,6.283); g.clip(); g.imageSmoothingEnabled=true; g.drawImage(off,0,0,S,S); g.restore();
  const R0=S/2/1.1; g.strokeStyle='rgba(255,255,255,.35)'; g.lineWidth=1.2; g.beginPath(); g.arc(S/2,S/2,R0*1.04,0,6.283); g.stroke();
  g.beginPath(); g.moveTo(S/2-S*.04,S/2-R0*1.04+1); g.lineTo(S/2,S/2-R0*1.04-S*.05); g.lineTo(S/2+S*.04,S/2-R0*1.04+1); g.stroke();
  g.fillStyle='rgba(8,10,14,.85)'; PTS.forEach(p=>{ g.beginPath(); g.arc(S/2+p.x*R0,S/2-p.y*R0,S>120?2.2:1.3,0,6.283); g.fill(); }); }
const redblue=v=>{ const t=clamp(v); return t<.5?[Math.round(40+t*2*60),Math.round(70+t*2*110),Math.round(160+t*2*80)]:[Math.round(100+(t-.5)*2*155),Math.round(180-(t-.5)*2*120),Math.round(240-(t-.5)*2*180)]; };
let lastRO=0;
function updateReadout(now){
  if(U.readout==='maps'){ const cv=$('#topo'); if(cv){ paintTopo(cv,PTS.map(p=>chanPower(p.n,mapBand))); $('#mapNote').textContent= mapBand==='alpha'?(M.eyes>.5?'Eyes closed: alpha pools over the parietal and occipital channels.':'Close your eyes and watch the back of the head.'):(M.math>.5?'Mental effort: beta rises over the front and centre.':'Try mental math and watch the front of the head.'); } }
  if(U.readout==='p300') drawERP();
  if(now-lastRO<90) return; lastRO=now;
  const k=U.readout;
  if(k==='p300'){ const post=posterior(); ROOT.querySelectorAll('#grid9 button').forEach((b,i)=>{ b.classList.toggle('tgt',i===M.target); b.classList.toggle('hl',M.round&&M.round.hl===i); b.classList.toggle('dec',M.decoded===i); b.querySelector('s').style.width=(post[i]*100)+'%'; });
    $('#p3txt').innerHTML = M.round?`Flash ${M.round.n}. Leading: <b>${ITEMS[post.indexOf(Math.max(...post))]}</b>, ${Math.round(Math.max(...post)*100)}%`: M.decoded!=null?`Decoded <b>${ITEMS[M.decoded]}</b> ${M.decoded===M.target?'correctly':'(wrong: try another round)'}. Averages use ${M.epT.length} target and ${M.epN.length} other flashes.`:'Pick an item, then run a round.'; }
  if(k==='ica'){ const c1=$('#icMap1'); if(c1 && !c1.dataset.done){ paintTopo(c1,PTS.map(p=>clamp(CH[p.n].bw*.9+Math.abs(CH[p.n].gz)*.5)),redblue); paintTopo($('#icMap2'),PTS.map(p=>CH[p.n].occ),redblue); paintTopo($('#icMap3'),PTS.map(p=>CH[p.n].fr*CH[p.n].fr),redblue); c1.dataset.done=1; }
    $('#ic1').classList.toggle('removed',!!M.ica); $('#ic1s').textContent=M.ica?'Removed from the data':'Eye blinks and movements';
    $('#icaNote').textContent=M.ica?'The frontal traces are clean now, with the brain activity underneath still there.':'Component 1 is strongest at the front, exactly where the eyes are. Remove it and watch the traces.'; }
  if(k==='multi'){ $('#oEEG').classList.add('on'); $('#oEOG').classList.toggle('on',now-M.evEOG<400); $('#oEMG').classList.toggle('on',now-M.evEMG<250); $('#oECG').classList.toggle('on',now-M.beat<150); }
}
function drawERP(){
  const cv=$('#erp'); if(!cv) return; const d=Math.min(2,devicePixelRatio||1), W=cv.clientWidth, H=120; if(cv.width!==W*d){ cv.width=W*d; cv.height=H*d; cv.style.height=H+'px'; }
  const g=cv.getContext('2d'); g.setTransform(d,0,0,d,0,0); g.clearRect(0,0,W,H);
  const X=s=>30+(W-40)*s/99, Y=v=>H/2-v*26;
  g.strokeStyle='rgba(0,0,0,.08)'; g.beginPath(); g.moveTo(30,H/2); g.lineTo(W-10,H/2); g.stroke();
  const t0=X(12.5), t300=X(12.5+37.5); g.setLineDash([3,3]); g.beginPath(); g.moveTo(t0,8); g.lineTo(t0,H-14); g.moveTo(t300,8); g.lineTo(t300,H-14); g.stroke(); g.setLineDash([]);
  g.fillStyle='#626973'; g.font='10.5px -apple-system, BlinkMacSystemFont, sans-serif'; g.fillText('flash',t0+3,H-4); g.fillText('300 ms',t300+3,H-4); g.fillText('Pz',4,12);
  const avg=eps=>{ if(!eps.length) return null; const a=new Array(100).fill(0); eps.forEach(e=>e.forEach((v,i)=>a[i]+=v)); const b=a.slice(0,12).reduce((x,y)=>x+y,0)/12; return a.map(v=>v/eps.length-b/eps.length); };
  [[avg(M.epN),'#8b93a1'],[avg(M.epT),ACC]].forEach(([a,c])=>{ if(!a) return; g.strokeStyle=c; g.lineWidth=2; g.beginPath(); a.forEach((v,i)=>{ const x=X(i), y=Y(clamp(v,-1.6,1.6)); i?g.lineTo(x,y):g.moveTo(x,y); }); g.stroke(); });
  g.fillStyle=ACC; g.fillText('your item',W-72,12); g.fillStyle='#8b93a1'; g.fillText('others',W-72,25);
}

/* ---------- traces ---------- */
const cv=$('#demoCanvas'), ctx=cv.getContext('2d'); let CW=0,CHh=0,rowH=40;
function sizeCanvas(){ const n=U.rows.length; rowH=n>4?36:n>2?44:58; const d=Math.min(2,devicePixelRatio||1); CW=cv.clientWidth; CHh=n*rowH+14; cv.width=CW*d; cv.height=CHh*d; cv.style.height=CHh+'px'; ctx.setTransform(d,0,0,d,0,0); }
on(window,'resize',sizeCanvas);
function drawCanvas(){
  const labelW=CW<460?70:86, W=CW-labelW-12; ctx.clearRect(0,0,CW,CHh); ctx.strokeStyle='rgba(0,0,0,.055)'; ctx.lineWidth=1;
  for(let s=0;s<=WIN;s++){ const x=labelW+W*s/WIN; ctx.beginPath(); ctx.moveTo(x,6); ctx.lineTo(x,CHh-6); ctx.stroke(); }
  ctx.font='12.5px -apple-system, BlinkMacSystemFont, sans-serif, sans-serif'; ctx.textBaseline='middle'; let startX=labelW;
  if(U.id==='browser'){ if(M.ble!=='live'){ U.rows.forEach((id,r)=>{ const y0=7+rowH*r+rowH/2; ctx.fillStyle='#6c737c'; ctx.fillText(CH[id].label,10,y0); ctx.strokeStyle='rgba(0,0,0,.10)'; ctx.beginPath(); ctx.moveTo(labelW,y0); ctx.lineTo(labelW+W,y0); ctx.stroke(); });
      ctx.fillStyle='#9aa2ad'; ctx.textAlign='center'; ctx.fillText(M.ble==='connecting'?'Opening the port…':'No signal yet. Connect over USB.',labelW+W/2,CHh/2); ctx.textAlign='left'; return; }
    const age=simT-M.liveSince; if(age<WIN) startX=labelW+W*(1-age/WIN); }
  U.rows.forEach((id,r)=>{ const c=CH[id], y0=7+rowH*r+rowH/2, amp=rowH*.42; const bank=U.bankColors?BANKC[Math.floor(MONT.indexOf(id)/8)]:null;
    ctx.fillStyle='#6e6e73'; ctx.fillText(c.label,10,y0);
    if(startX>labelW){ ctx.strokeStyle='rgba(0,0,0,.10)'; ctx.beginPath(); ctx.moveTo(labelW,y0); ctx.lineTo(startX,y0); ctx.stroke(); }
    ctx.strokeStyle=bank||COL[c.col]; ctx.globalAlpha=.95; ctx.lineWidth=1.3; ctx.beginPath(); let first=true; const step=Math.max(1,Math.floor(N/Math.min(N,W)));
    const clean=U.id==='ica'&&M.ica&&c.art;
    for(let i=0;i<N;i+=step){ const x=labelW+W*i/(N-1); if(x<startX) continue; const idx=(head+1+i)%N; const v=clean?c.buf[idx]-c.art[idx]*.96:c.buf[idx]; const y=y0-clamp(v,-1.6,1.6)*amp*.55; first?ctx.moveTo(x,y):ctx.lineTo(x,y); first=false; }
    ctx.stroke(); ctx.globalAlpha=1; });
  if(U.id==='p300'){ for(const f of M.flashes){ const age=simT-f.t; if(age<0||age>WIN) continue; const x=labelW+W*(1-age/WIN); ctx.strokeStyle=f.target?ACC:'rgba(255,255,255,.18)'; ctx.lineWidth=f.target?1.4:1; ctx.beginPath(); ctx.moveTo(x,4); ctx.lineTo(x,CHh-4); ctx.stroke(); } }
}

