function drawHum(){ const cvh=$('#humCanvas'); const d=Math.min(2,devicePixelRatio||1), W=cvh.clientWidth, H=90; if(cvh.width!==W*d){ cvh.width=W*d; cvh.height=H*d; cvh.style.height=H+'px'; }
  const g=cvh.getContext('2d'); g.setTransform(d,0,0,d,0,0); g.clearRect(0,0,W,H); g.font='12px -apple-system, BlinkMacSystemFont, sans-serif'; g.fillStyle='#8e96a0'; g.fillText('Cz, 1 s',10,16);
  g.strokeStyle=mains?'#ff5a74':'#3fc8ff'; g.lineWidth=1.2; g.beginPath(); const c=CH.Cz.buf;
  for(let i=0;i<W-70;i++){ const s=Math.floor(i/(W-70)*125); const idx=(head-125+s+N)%N; const t=simT-1+i/(W-70); const hum=mains?.9*Math.sin(6.283*50*t*.98)+.3*Math.sin(6.283*150*t):0; const y=H/2+8-(c[idx]*.5+hum)*16; i?g.lineTo(60+i,y):g.moveTo(60+i,y); } g.stroke(); }

