// step 5: banks → scalp regions
(function(){
  const s=$('#wire'), cx=140, cy=180, Rr=128;
  let h=`<ellipse cx="${cx-Rr-4}" cy="${cy}" rx="12" ry="26" fill="#23272e"/><ellipse cx="${cx+Rr+4}" cy="${cy}" rx="12" ry="26" fill="#23272e"/><path d="M${cx-16},${cy-Rr+6} Q${cx},${cy-Rr-26} ${cx+16},${cy-Rr+6}" fill="#262a31"/>
    <circle cx="${cx}" cy="${cy}" r="${Rr}" fill="#1f232a" stroke="rgba(255,255,255,.12)"/>`;
  MONT.forEach((n,i)=>{ const x=cx+P1020[n][0]*Rr*.88, y=cy-P1020[n][1]*Rr*.88, b=Math.floor(i/8);
    h+=`<g class="wd" data-b="${b}"><circle cx="${x}" cy="${y}" r="6" fill="#12151a" stroke="${BANKC[b]}" stroke-width="1.8"/><circle cx="${x}" cy="${y}" r="2.3" fill="${BANKC[b]}"/><text x="${x}" y="${y+15}" text-anchor="middle" fill="#9aa2ad" style="font-size:8.5px">${n}</text></g>`; });
  h+=`<path d="M${cx-Rr-4},${cy+14} l6,-6 l6,6 l-6,6 Z" fill="#12151a" stroke="#e8ebef"/><text x="${cx-Rr+2}" y="${cy+40}" text-anchor="middle" fill="#cfd4da" style="font-size:10.5px;font-weight:600">REF</text>
    <path d="M${cx+Rr-8},${cy+14} l6,-6 l6,6 l-6,6 Z" fill="#12151a" stroke="#e8ebef"/><text x="${cx+Rr-2}" y="${cy+40}" text-anchor="middle" fill="#cfd4da" style="font-size:10.5px;font-weight:600">BIAS</text>`;
  const ox=440, oy=180, r=86, oct=[...Array(8)].map((_,k)=>{ const a=(22.5+45*k)*Math.PI/180; return `${ox+r*Math.cos(a)},${oy+r*Math.sin(a)}`; }).join(' ');
  h+=`<g transform="rotate(-135 ${ox} ${oy})"><image x="${ox-82}" y="${oy-82}" width="164" height="164" href="${BOARD_PHOTO}"/></g><text x="${ox}" y="${oy+128}" text-anchor="middle" fill="#efe3ff" style="font-size:11px;font-weight:700">IronBCI-32</text>`;
  [135,225,315,45].forEach((a,b)=>{ const rad=a*Math.PI/180, ap=r*Math.cos(Math.PI/8); h+=`<g class="bk" data-b="${b}" style="cursor:pointer"><g transform="translate(${ox},${oy}) rotate(${a})"><rect x="${ap-10}" y="-30" width="30" height="60" rx="3" fill="${BANKC[b]}" fill-opacity=".85"/></g>
      <text x="${ox+Math.cos(rad)*(ap+42)}" y="${oy+Math.sin(rad)*(ap+42)+4}" text-anchor="middle" fill="${BANKC[b]}" style="font-size:11.5px;font-weight:700">${['1–8','9–16','17–24','25–32'][b]}</text></g>`; });
  s.innerHTML=h;
  const names=['Bank 1: CH1 to 8, plus REF and BIAS','Bank 2: CH9 to 16','Bank 3: CH17 to 24','Bank 4: CH25 to 32'];
  $('#bankList').innerHTML=names.map((n,b)=>`<div data-b="${b}" style="--bc:${BANKC[b]}"><i></i><b>${n}</b><span>${MONT.slice(b*8,b*8+8).join(', ')}</span></div>`).join('');
  const hl=b=>{ s.querySelectorAll('.wd').forEach(n=>n.style.opacity=b==null||+n.dataset.b===b?1:.15); s.querySelectorAll('.bk').forEach(n=>n.style.opacity=b==null||+n.dataset.b===b?1:.3); ROOT.querySelectorAll('#bankList div').forEach(n=>n.classList.toggle('on',+n.dataset.b===b)); };
  [...s.querySelectorAll('.bk'),...ROOT.querySelectorAll('#bankList div')].forEach(n=>{ n.addEventListener('pointerenter',()=>hl(+n.dataset.b)); n.addEventListener('pointerleave',()=>hl(null)); });
})();

// step 6: gel map
const GEL=new Array(32).fill(false);
function renderGel(){
  const s=$('#gelMap'); let h=`<ellipse cx="-160" cy="0" rx="14" ry="30" fill="#23272e"/><ellipse cx="160" cy="0" rx="14" ry="30" fill="#23272e"/><path d="M-18,-146 Q0,-176 18,-146" fill="#262a31"/><circle r="150" fill="#1f232a" stroke="rgba(255,255,255,.12)"/>`;
  MONT.forEach((n,i)=>{ const x=P1020[n][0]*132, y=-P1020[n][1]*132, g=GEL[i];
    h+=`<g class="gd" data-i="${i}" style="cursor:pointer" tabindex="0" role="button" aria-pressed="${g}" aria-label="${n}">${g?`<circle cx="${x}" cy="${y}" r="15" fill="#8fd3ff" fill-opacity=".25"/>`:''}<circle cx="${x}" cy="${y}" r="10" fill="${g?'#45dd8b':'#2a1519'}" stroke="${g?'#9df0c0':'#ff5a74'}" stroke-width="1.6"/><text x="${x}" y="${y+3.5}" text-anchor="middle" fill="${g?'#062b17':'#ffb4c0'}" style="font-size:8px;font-weight:700">${n}</text></g>`; });
  s.innerHTML=h; const n=GEL.filter(Boolean).length;
  $('#gelProgress').innerHTML= n===32?'<b>All 32 gelled.</b> On to streaming.':`<b>${n} of 32</b> gelled`; $('#s6').classList.toggle('done',n===32);
  s.querySelectorAll('.gd').forEach(g=>{ const f=()=>{ GEL[+g.dataset.i]=!GEL[+g.dataset.i]; renderGel(); }; g.addEventListener('click',f); g.addEventListener('keydown',e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); f(); } }); });
}
(function(){ const c=$('#gelCtl'); ['Bank 1','Bank 2','Bank 3','Bank 4'].forEach((l,b)=>{ const x=document.createElement('button'); x.className='ctl'; x.style.setProperty('--sig',BANKC[b]); x.innerHTML=`<i class="bdot" style="background:${BANKC[b]}"></i>Gel ${l.toLowerCase()}`; x.addEventListener('click',()=>{ for(let i=b*8;i<b*8+8;i++) GEL[i]=true; renderGel(); }); c.appendChild(x); });
  const r=document.createElement('button'); r.className='ctl'; r.textContent='Start again'; r.addEventListener('click',()=>{ GEL.fill(false); renderGel(); }); c.appendChild(r); renderGel(); })();

