const start=(location.hash||'').slice(1);
selectUse(USES.some(u=>u.id===start)?start:'maps');
if(USES.some(u=>u.id===start)) later(()=>$('#where').scrollIntoView(),50);
for(let i=0;i<N;i++) advance(1/FS);
let last=0, vis=true, visHum=false;
{ const io=new IntersectionObserver(es=>{ vis=es[0].isIntersecting; },{rootMargin:'100px'}); io.observe($('#useStage')); cleanups.push(()=>io.disconnect()); }
{ const io=new IntersectionObserver(es=>{ visHum=es[0].isIntersecting; },{rootMargin:'100px'}); io.observe($('#humCanvas')); cleanups.push(()=>io.disconnect()); }
function frame(now){
  if(stopped) return;
  const dt=Math.min(.05,(now-(last||now))/1000); last=now;
  if(!reduce) advance(dt); else if(Math.floor(now/250)!==Math.floor((now-dt*1000)/250)) advance(.25);
  stepRound();
  if(vis){ drawCanvas(); updateReadout(now); }
  if(visHum) drawHum();
  if(!stopped) rafId=requestAnimationFrame(frame);
}
if(!stopped) rafId=requestAnimationFrame(frame);


return () => {
  stopped = true;
  cancelAnimationFrame(rafId);
  timers.forEach((id) => clearTimeout(id));
  timers.clear();
  cleanups.forEach((fn) => fn());
  ROOT.innerHTML = PRISTINE;
};
